<?php get_header(); ens_breadcrumb(get_the_title()); $id=get_the_ID(); $cat=get_the_terms($id,'ens_product_cat'); $gallery_ids=array_filter(array_map('absint',explode(',',(string)get_post_meta($id,'_ens_gallery',true)))); $stock=get_post_meta($id,'_ens_stock',true)?:'En stock'; $brand=get_post_meta($id,'_ens_brand',true); $unit=get_post_meta($id,'_ens_unit',true); $specs=preg_split('/\r\n|\r|\n/',(string)get_post_meta($id,'_ens_specs',true)); $main_image=get_post_thumbnail_id($id); if(!$main_image && $gallery_ids)$main_image=$gallery_ids[0]; ?><main class="ens-container ens-main"><div class="ens-product-single"><div class="ens-product-gallery"><div class="ens-product-visual"><?php if($main_image): ?><img id="ens-main-product-image" src="<?php echo esc_url(wp_get_attachment_image_url($main_image,'large')); ?>" alt="<?php echo esc_attr(get_the_title()); ?>"><?php else: ?><div class="ens-no-product-image">Imagen no disponible</div><?php endif; ?></div><?php if($gallery_ids): ?><div class="ens-product-thumbs"><?php if(get_post_thumbnail_id($id)): ?><button class="ens-product-thumb ens-active" data-ens-gallery="<?php echo esc_attr(wp_get_attachment_image_url(get_post_thumbnail_id($id),'large')); ?>"><img src="<?php echo esc_url(wp_get_attachment_image_url(get_post_thumbnail_id($id),'thumbnail')); ?>" alt=""></button><?php endif; ?><?php foreach($gallery_ids as $image_id): ?><button class="ens-product-thumb" data-ens-gallery="<?php echo esc_attr(wp_get_attachment_image_url($image_id,'large')); ?>"><img src="<?php echo esc_url(wp_get_attachment_image_url($image_id,'thumbnail')); ?>" alt=""></button><?php endforeach; ?></div><?php endif; ?></div><div class="ens-product-copy"><div class="ens-kicker"><?php echo esc_html(($cat && !is_wp_error($cat))?$cat[0]->name:'Herramientas'); ?></div><h1><?php the_title(); ?></h1><div class="ens-lead"><?php the_content(); ?></div><div class="ens-product-price"><small>Precio final</small><?php echo esc_html(ens_price($id)); ?></div><div class="ens-product-meta"><span class="ens-stock <?php echo $stock==='Agotado'?'ens-stock-out':''; ?>"><?php echo esc_html($stock); ?></span><?php if($brand): ?><span>Marca: <?php echo esc_html($brand); ?></span><?php endif; ?><?php if($unit): ?><span>Venta por: <?php echo esc_html($unit); ?></span><?php endif; ?><?php $sku=get_post_meta($id,'_ens_sku',true); if($sku): ?><span>SKU: <?php echo esc_html($sku); ?></span><?php endif; ?></div><button class="ens-btn ens-btn-primary" data-ens-add="<?php echo esc_attr($id); ?>">🛒 Agregar al carrito</button><a class="ens-btn ens-btn-whatsapp ens-product-wa" href="https://wa.me/<?php echo esc_attr(preg_replace('/\D+/','',get_theme_mod('ens_whatsapp','5491100000000'))); ?>?text=<?php echo rawurlencode('Hola, quiero consultar por: '.get_the_title($id)); ?>" target="_blank" rel="noopener">💬 Consultar por WhatsApp</a><?php if(array_filter($specs)): ?><div class="ens-specs"><h2>Especificaciones</h2><?php foreach($specs as $spec){$parts=explode('|',$spec,2);if(count($parts)===2)echo '<div class="ens-spec"><span>'.esc_html(trim($parts[0])).'</span><strong>'.esc_html(trim($parts[1])).'</strong></div>';} ?></div><?php endif; ?><hr class="ens-hr"><a class="ens-btn ens-btn-outline" href="<?php echo esc_url(get_permalink(get_page_by_path('contacto')) ?: '#'); ?>">Consultar por este producto</a></div></div><?php if($cat && !is_wp_error($cat)): $related=new WP_Query(array('post_type'=>'ens_product','posts_per_page'=>3,'post__not_in'=>array($id),'tax_query'=>array(array('taxonomy'=>'ens_product_cat','field'=>'term_id','terms'=>$cat[0]->term_id)))); if($related->have_posts()): ?><section class="ens-related"><div class="ens-page-head"><h2>También te puede servir</h2></div><div class="ens-products"><?php while($related->have_posts()):$related->the_post();ens_product_card(get_the_ID());endwhile;wp_reset_postdata(); ?></div></section><?php endif; endif; ?></main><a class="ens-whatsapp-sticky" href="https://wa.me/<?php echo esc_attr(preg_replace('/\D+/','',get_theme_mod('ens_whatsapp','5491100000000'))); ?>" target="_blank" rel="noopener">💬 WhatsApp</a><?php get_footer(); ?>